import hashlib
import itertools
import string

def hash_password(password):
    return hashlib.sha256(password.encode()).hexdigest()

def generate_rainbow_table(size, length):
    table = {}
    for i in range(size):
        for password in itertools.product(string.ascii_lowercase, repeat=length):
            hashed = hash_password(''.join(password))
            table[hashed] = ''.join(password)
    return table

def rainbow_attack(rainbow_table, hashed_passwords):
    for hashed_password in hashed_passwords:
        if hashed_password in rainbow_table:
            return rainbow_table[hashed_password]
